  ALTER TYPE public.job_status ADD VALUE IF NOT EXISTS 'declined';
  ALTER TYPE public.job_status ADD VALUE IF NOT EXISTS 'no_mechanic_found';
EXCEPTION WHEN OTHERS THEN
  NULL;
END $$;

-- 4. Ensure required app_settings are seeded
